#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_typeX;
uniform float amzp_scalex;
uniform float amzp_progressa;
uniform float amzp_scale;
uniform float amzp_progressb;
uniform float amzp_progressc;
uniform float amzp_invertxy;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float amzp_bright;
uniform float amzp_alpha;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
        float hash(float f){return fract(sin(f*32.34182) * 43758.5453);}
        float hash(float2 p){return fract(sin(dot(p.xy ,float2(12.9898,78.233))) * 43758.5453);}
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= (amzp_scalex>0.5)? (amzp_scale+3.0) : amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((30.0+amzp_position.x), (-105.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 xnxx = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        xnxx.y *=layer.y/layer.x;
     float4 fragColor;
               float
                t = amzp_progressa,
                sgn,h,h2,h3,band,ff,df=0.;
            float2
                s = float2(screen.zw.x,screen.zw.y),
                uv= satriyaid;
                float3 dir;
                if(int(amzp_typeX)==0) { dir =-normalize(float3(-10.,2.*t/1000.,-4.*t/1000.)); }
                else if(int(amzp_typeX)==1) { (amzp_invertxy>0.5)? dir =-normalize(float3(-10.,2.*sin(t/(101.0-amzp_progressc)),5.0*sin(t/(101.0-amzp_progressb)))) : dir =-normalize(float3(-10., 2.*sin(t/(101.0-amzp_progressb)),5.0*sin(t/(101.0-amzp_progressc)))); }
                else if(int(amzp_typeX)==2) { (amzp_invertxy>0.5)? dir =-normalize(float3(-10.,2.*sin(t/(101.0-amzp_progressc)),5.0*tan(t/(101.0-amzp_progressb)))) : dir =-normalize(float3(-10.,2.*tan(t/(101.0-amzp_progressb)),5.0*sin(t/(101.0-amzp_progressc)))); }
                else if(int(amzp_typeX)==3) { (amzp_invertxy>0.5)? dir =-normalize(float3(-10.,2.*sin(t/(101.0-amzp_progressc)),5.0*ceil(t/(101.0-amzp_progressb)))) : dir =-normalize(float3(-10.,2.*ceil(t/(101.0-amzp_progressb)),5.0*sin(t/(101.0-amzp_progressc)))); uv /= 0.05; }
                float3 up = float3(0.,0.,1.);
                float3 k=float3(1,2,3)/3.;
                float3 col=k-k;
            up=normalize(up-dir*dot(dir,up));
            dir=normalize(dir+=cross(dir,up)*uv.x+s.y/s.x*up*uv.y);
            for (float a =0.;a<3.14159; a += 1.152)
            {
                df += 0.05;
                dir *= float3x3(1.,1.,1.,0.,cos(a),-sin(a),0.,sin(a),cos(a));
                float2 p = dir.zx / max(.001, abs(dir.y))*float2(3., 0.18);
                p.y += t * 12. + a ;
                sgn = sign(dir.y);
                h = hash(floor((p+=.5+a)*sgn));
                h2 = hash(floor(p.y/6.));
                h3 = hash(floor(p.y/20.*a)+sgn);
                band = abs(p.x) < 2. + floor(30.*h3*h3) ? 1. : 0.;
                ff = h2 < .5 ? smoothstep(.6, 0.,length( mod(p, float2(1.)) - .5))*6. : 2.;
                h = h < h2/1.2 + .1 ? 1. : 0.;
                col += .9 * mix(k, clamp(abs(fract(h2/5.+t/30.+k)*6. - 3.) - k, 0., 1.), .9) * h * band * 3. * ff * pow(abs(dir.y),0.5);
            }
            fragColor.rgb = clamp(col*.25, 0., 1.)+df;
            fragColor.a = 1.0;
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
